"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

/*
 * Chrome Azure Slider — a recessed steel channel; the filled range is the
 * azure alloy and the thumb is a raised chrome knob with a wet sheen, matching
 * the switch.
 */

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Slider = React.forwardRef<
  HTMLDivElement,
  WithClassName<SliderPrimitive.Root.Props>
>(({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track
            data-slot="slider-track"
            className={cn(
              "relative h-1.5 w-full grow overflow-hidden rounded-full border border-white/10",
              "bg-input [box-shadow:var(--shadow-inset)]"
            )}
          >
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full [background:var(--surface-on)]" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "relative block h-4 w-4 overflow-hidden rounded-full [background:var(--knob-off)]",
                "[box-shadow:var(--shadow-knob)]",
                "transition-[transform] duration-fast hover:scale-110",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            >
              <span aria-hidden className="absolute inset-0 rounded-full [background:var(--gloss-top)]" />
            </SliderPrimitive.Thumb>
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
